        if (
            owner_id is not None
            and owner_id in owner_ids
            and manager_id in manager_ids
            and owner_id != manager_id
        ):
            Membership.objects.using(database).get_or_create(
                owner_id=owner_id,
                user_id=manager_id,
            )


